// The cloth made very large: the long threads (the warp, blue) and the cross threads (the weft, yellow) go over and
// under each other in turn: the plain weave. Nothing ties them: each thread is held only by the bends of the others,
// and that is the whole strength of cloth. The bright thread is the one the shuttle has just laid.
const warpM = W.fabric('#2f5f9a'), weftM = W.fabric('#e8c62a'), newM = new THREE.MeshStandardMaterial({ color: 0xfff1a8, emissive: 0xffd23a, emissiveIntensity: 1.2, roughness: 0.8 });
const N = 7, P = 26, R = 6.5;
const wave = (i, along, phase) => { const pts = []; for (let k = 0; k <= 28; k++) { const u = -P * N / 2 + (k / 28) * P * N, h = Math.cos((u / P + 0.5) * Math.PI) * R * 1.05 * phase; pts.push(along === 'x' ? [u, h, (i - (N - 1) / 2) * P] : [(i - (N - 1) / 2) * P, h, u]); } return pts; };
const wp = W.group(), wf = W.group(), nw = W.group();
for (let i = 0; i < N; i++) wp.add(W.mesh(W.tube(wave(i, 'x', i % 2 ? 1 : -1), R, 60), warpM));
for (let i = 0; i < N - 1; i++) wf.add(W.mesh(W.tube(wave(i, 'z', i % 2 ? -1 : 1), R, 60), weftM));
const last = W.mesh(W.tube(wave(N - 1, 'z', (N - 1) % 2 ? -1 : 1), R, 60), newM);
nw.add(last);
W.add(wp, { label: 'పడుగు (నిలువు దారాలు)' });
W.add(wf, { label: 'పేక (అడ్డ దారాలు)' });
W.add(nw, { label: 'ఇప్పుడే వేసిన పేక' });
W.onTick((t) => { const k = (t % 3) / 3; last.position.x = (1 - Math.min(1, k * 2.2)) * 60; newM.emissiveIntensity = 0.5 + 1.2 * Math.abs(Math.sin(t * 3)); });
